import{_ as s,o,c as n,a2 as r}from"./chunks/framework.Zh78JZbW.js";const p=JSON.parse('{"title":"Ajouter des mods et du contenu","description":"","frontmatter":{},"headers":[],"relativePath":"guide/mods.md","filePath":"guide/mods.md"}'),a={name:"guide/mods.md"};function t(i,e,l,u,d,c){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="ajouter-des-mods-et-du-contenu" tabindex="-1">Ajouter des mods et du contenu <a class="header-anchor" href="#ajouter-des-mods-et-du-contenu" aria-label="Permalink to &quot;Ajouter des mods et du contenu&quot;">​</a></h1><p>Le contenu se gère depuis la page de l&#39;instance : cliquez sur son nom dans la colonne de gauche, puis sur l&#39;onglet <strong>Contenu</strong>.</p><ol><li>Choisissez l&#39;onglet : <strong>Mods</strong>, <strong>Resource packs</strong>, <strong>Datapacks</strong> ou <strong>Shaders</strong>. Un onglet grisé n&#39;est pas disponible pour cette instance (par exemple, les mods en Vanilla).</li><li>Par défaut, Kodus affiche les contenus les plus téléchargés pour votre version et votre loader. Utilisez la barre de recherche pour trouver un contenu précis.</li><li>Cliquez sur <strong>Installer</strong>. Kodus sélectionne la version compatible et installe les dépendances nécessaires.</li><li>Lancez le jeu : le mod est actif.</li></ol><h2 id="fiche-d-un-mod" tabindex="-1">Fiche d&#39;un mod <a class="header-anchor" href="#fiche-d-un-mod" aria-label="Permalink to &quot;Fiche d&#39;un mod&quot;">​</a></h2><p>Cliquez sur l&#39;icône ou le nom d&#39;un mod pour ouvrir sa fiche : description complète, images, versions de Minecraft prises en charge, nécessité de l&#39;installer sur un serveur, et liens vers sa page Modrinth ou son wiki. Depuis la fiche, vous pouvez l&#39;installer dans l&#39;instance ouverte, l&#39;ajouter à une autre instance, ou <strong>jouer avec ce mod</strong> dans une nouvelle instance préparée automatiquement.</p><h2 id="la-colonne-«-installes-»" tabindex="-1">La colonne « Installés » <a class="header-anchor" href="#la-colonne-«-installes-»" aria-label="Permalink to &quot;La colonne « Installés »&quot;">​</a></h2><ul><li>L&#39;interrupteur active ou désactive un mod, un pack de ressources, un datapack ou un shader sans le supprimer (utile pour identifier un mod à l&#39;origine d&#39;un plantage). Un pack décompressé (dossier) ne peut pas être désactivé.</li><li>La croix supprime le fichier.</li><li>Le bouton <strong>Tout mettre à jour</strong> apparaît lorsque des mises à jour compatibles avec votre version de Minecraft sont disponibles.</li><li>Cliquez sur le nom d&#39;un mod pour ouvrir sa fiche.</li></ul><h3 id="fichiers-ajoutes-a-la-main" tabindex="-1">Fichiers ajoutés à la main <a class="header-anchor" href="#fichiers-ajoutes-a-la-main" aria-label="Permalink to &quot;Fichiers ajoutés à la main&quot;">​</a></h3><p>Vous pouvez aussi déposer des fichiers directement dans le dossier de l&#39;instance (<strong>Ouvrir le dossier</strong>) : ils apparaissent dans la colonne « Installés » dès que vous revenez dans Kodus. Kodus reconnaît ceux qui viennent de Modrinth, même renommés : ils affichent leur vrai nom et reçoivent les mises à jour comme les autres. Les fichiers introuvables sur Modrinth sont indiqués « Ajouté à la main » : ils fonctionnent normalement, mais leurs mises à jour sont à faire vous-même.</p><h2 id="mods-recommandes" tabindex="-1">Mods recommandés <a class="header-anchor" href="#mods-recommandes" aria-label="Permalink to &quot;Mods recommandés&quot;">​</a></h2><p>Parmi les plus utilisés : <strong>Sodium</strong> (performances), <strong>Iris</strong> (shaders), <strong>Mod Menu</strong> (liste des mods en jeu), <strong>AppleSkin</strong> (affichage de la faim et de la saturation), <strong>Xaero&#39;s Minimap</strong> (minicarte).</p><h2 id="cas-particuliers" tabindex="-1">Cas particuliers <a class="header-anchor" href="#cas-particuliers" aria-label="Permalink to &quot;Cas particuliers&quot;">​</a></h2><ul><li><strong>Shaders</strong> : le mod Iris est requis. Kodus propose un bouton <strong>Installer Iris</strong> s&#39;il est absent.</li><li><strong>Datapacks</strong> : ils s&#39;installent dans un monde. Créez d&#39;abord un monde en jeu, puis sélectionnez-le dans l&#39;onglet Datapacks.</li><li><strong>Mod obtenu ailleurs</strong> (fichier <code>.jar</code>) : cliquez sur <strong>Ouvrir le dossier</strong> et déposez-y le fichier. Vérifiez qu&#39;il correspond à votre version et à votre loader.</li></ul>',13)])])}const h=s(a,[["render",t]]);export{p as __pageData,h as default};
